function totalCheckouts(counts) {
  let total = 0;
  for (const count of counts) {
    total += count;
  }
  return total;
}

jsb-object-build.script.js:
function makeRepairOrder(issue, minutes, urgent) {
  return { urgent: urgent, issue: issue, minutes: minutes };
}

jsb-object-list.script.js:
function listReadyPickups(parcels) {
  const labels = [];
  for (const parcel of parcels) {
    if (parcel.ready) {
      labels.push(parcel.label);
    }
  }
  return labels;
}
